import { test, expect } from '@playwright/test';

test.describe('Optimistic UI Updates on Like Button', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/posts');
  });

  test('should display optimistic like count and update on successful API call', async ({ page }) => {
    // Intercept the API call for liking a post
    await page.route('**/api/posts/1/like', (route) => {
      route.continue();
    });

    // Get the like button using getByRole
    const likeButton = page.getByRole('button', { name: /like this post/i });
    await expect(likeButton).toBeVisible();

    // Get the like count using getByRole
    const likeCount = page.getByRole('heading', { name: /likes: 0/i });
    await expect(likeCount).toBeVisible();

    // Get the like button using getByRole
    const likeButton = page.getByRole('button', { name: /like this post/i });
    await likeButton.click();

    // Verify optimistic UI is displayed
    await expect(likeCount).toContainText('likes: 1');
    await expect(likeButton).toBeDisabled();

    // Verify like button is disabled after successful API call
    await expect(likeButton).toBeDisabled();

    // Verify like count is updated on the page
    const likeCount = page.getByRole('heading', { name: /likes: 1/i });
    await expect(likeCount).toBeVisible();

    // Verify like count is displayed
    await expect(likeCount).toContainText('likes: 1');

    // Verify like button is enabled after successful API call
    await expect(likeButton).not.toBeDisabled();

    // Verify like button is clickable again
    await expect(likeButton).toBeEnabled();

    // Verify like count is incremented on second click
    await likeButton.click();
    await expect(likeCount).toContainText('likes: 2');

    // Verify like button is still clickable
    await expect(likeButton).toBeEnabled();
  });

  test('should revert optimistic UI on failed API call', async ({ page }) => {
    // Intercept the API call for liking a post with error
    await page.route('**/api/posts/1/like', (route) => {
      route.abort('failed');
    });

    // Get the like button using getByRole
    const likeButton = page.getByRole('button', { name: /like this post/i });
    await expect(likeButton).toBeVisible();

    // Get the like count using getByRole
    const likeCount = page.getByRole('heading', { name: /likes: 0/i });
    await expect(likeCount).toBeVisible();

    // Get the like button using getByRole
    const likeButton = page.getByRole('button', { name: /like this post/i });
    await likeButton.click();

    // Verify optimistic UI is displayed
    await expect(likeCount).toContainText('likes: 1');
    await expect(likeButton).toBeDisabled();

    // Verify error message is displayed
    const errorMessage = page.getByText(/failed to like post/i);
    await expect(errorMessage).toBeVisible();

    // Verify like button is still disabled
    await expect(likeButton).toBeDisabled();

    // Verify like count is not incremented
    const likeCount = page.getByRole('heading', { name: /likes: 1/i });
    await expect(likeCount).toContainText('likes: 1');

    // Verify error message is still visible
    await expect(errorMessage).toBeVisible();

    // Verify like button is still clickable
    await expect(likeButton).toBeEnabled();
  });
});
